DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Anomaly Guard — Mobile Money Fraud Checker</title>\n  <style>\n    :root {\n      --bg: #f5f7fa; --card: #ffffff; --text: #111827; --muted: #6b7280;\n      --border: #e5e7eb; --primary: #111827; --primary-hover: #1f2937;\n      --safe-bg: #ecfdf5; --safe-border: #a7f3d0; --safe-text: #065f46;\n      --warn-bg: #fef2f2; --warn-border: #fecaca; --warn-text: #991b1b;\n      --amber-bg: #fffbeb; --amber-border: #fde68a; --amber-text: #92400e;\n      --blue-bg: #eff6ff; --blue-border: #bfdbfe; --blue-text: #1e40af;\n      --radius: 14px;\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n      background: var(--bg); color: var(--text); line-height: 1.5;\n      min-height: 100vh; display: flex; flex-direction: column;\n    }\n    .topbar {\n      background: var(--card); border-bottom: 1px solid var(--border);\n      padding: 16px 24px; display: flex; align-items: center; justify-content: space-between; gap: 16px;\n    }\n    .brand { display: flex; align-items: center; gap: 12px; }\n    .logo {\n      width: 38px; height: 38px; border-radius: 10px; background: #111827; color: #fff;\n      display: grid; place-items: center; font-weight: 700; font-size: 17px; flex-shrink: 0;\n    }\n    .brand h1 { margin: 0; font-size: 18px; font-weight: 700; }\n    .brand p { margin: 0; font-size: 13px; color: var(--muted); }\n    .top-actions { display: flex; align-items: center; gap: 10px; }\n    .pill {\n      font-size: 12px; font-weight: 600; padding: 5px 10px; border-radius: 999px;\n      background: var(--safe-bg); color: var(--safe-text); border: 1px solid var(--safe-border);\n    }\n    .pill.waking { background: var(--amber-bg); color: var(--amber-text); border-color: var(--amber-border); }\n    .pill.offline { background: var(--warn-bg); color: var(--warn-text); border-color: var(--warn-border); }\n\n    .wake-banner {\n      display: none; background: var(--amber-bg); border-bottom: 1px solid var(--amber-border);\n      color: var(--amber-text); text-align: center; padding: 9px 16px; font-size: 13px; font-weight: 500;\n    }\n    .wake-banner.show { display: block; }\n\n    .btn-ghost {\n      background: #fff; border: 1px solid var(--border); color: var(--text);\n      padding: 8px 14px; border-radius: 10px; font-size: 13px; font-weight: 600;\n      cursor: pointer; transition: background 0.15s; text-decoration: none; display: inline-block;\n    }\n    .btn-ghost:hover { background: #f9fafb; }\n    .btn-ghost.active-filter { background: #111827; color: #fff; border-color: #111827; }\n\n    .container { max-width: 1060px; width: 100%; margin: 26px auto 0; padding: 0 20px 48px; flex: 1; }\n    .tabs { display: flex; gap: 8px; margin-bottom: 22px; flex-wrap: wrap; }\n    .tab {\n      border: 1px solid var(--border); background: var(--card); color: var(--muted);\n      padding: 11px 18px; border-radius: 11px; font-size: 14px; font-weight: 600;\n      cursor: pointer; transition: all 0.15s;\n    }\n    .tab:hover { color: var(--text); border-color: #cbd5e1; }\n    .tab.active { background: var(--primary); color: #fff; border-color: var(--primary); }\n\n    .panel { display: none; animation: fadeIn 0.18s ease; }\n    .panel.active { display: block; }\n    @keyframes fadeIn { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: translateY(0); } }\n\n    .grid-2 { display: grid; grid-template-columns: 1.06fr 0.94fr; gap: 22px; align-items: start; }\n    @media (max-width: 840px) { .grid-2 { grid-template-columns: 1fr; } }\n\n    .card {\n      background: var(--card); border: 1px solid var(--border);\n      border-radius: var(--radius); padding: 22px; box-shadow: 0 1px 2px rgba(0,0,0,0.03);\n    }\n    .card h2 { margin: 0 0 6px; font-size: 17px; }\n    .subtitle { margin: 0 0 16px; font-size: 14px; color: var(--muted); }\n\n    .examples-label { font-size: 12px; font-weight: 700; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; letter-spacing: 0.03em; }\n    .examples { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }\n    .example-btn {\n      border: 1px solid var(--border); background: #f9fafb; color: var(--text);\n      padding: 7px 12px; border-radius: 999px; font-size: 13px; font-weight: 500;\n      cursor: pointer; transition: all 0.15s;\n    }\n    .example-btn:hover { background: #eef2f7; border-color: #94a3b8; }\n\n    .form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n    @media (max-width: 560px) { .form-grid { grid-template-columns: 1fr; } }\n    .field { display: flex; flex-direction: column; gap: 6px; }\n    .field.full { grid-column: 1 / -1; }\n    label { font-size: 13px; font-weight: 600; color: #374151; }\n    input, select {\n      width: 100%; padding: 10px 12px; border: 1px solid #d1d5db; border-radius: 10px;\n      font-size: 14px; background: #fff; color: var(--text);\n    }\n    input:focus, select:focus { outline: 2px solid #111827; border-color: #111827; }\n\n    .math-hint {\n      font-size: 12px; font-weight: 600; padding: 6px 10px; border-radius: 8px;\n      display: flex; align-items: center; justify-content: space-between; gap: 8px;\n    }\n    .math-hint.ok { background: var(--safe-bg); color: var(--safe-text); }\n    .math-hint.warn { background: var(--amber-bg); color: var(--amber-text); }\n    .link-btn {\n      background: none; border: none; color: inherit; font-weight: 700;\n      text-decoration: underline; cursor: pointer; font-size: 12px; padding: 0;\n    }\n\n    .btn-primary {\n      width: 100%; margin-top: 16px; padding: 13px 16px; background: var(--primary); color: #fff;\n      border: none; border-radius: 11px; font-size: 15px; font-weight: 600; cursor: pointer; transition: background 0.15s;\n    }\n    .btn-primary:hover { background: var(--primary-hover); }\n    .btn-primary:disabled { opacity: 0.6; cursor: wait; }\n\n    .result-empty { text-align: center; padding: 52px 20px; color: var(--muted); font-size: 14px; }\n    .verdict-box { border-radius: 12px; padding: 20px; margin-bottom: 14px; border: 1px solid var(--border); }\n    .verdict-box.safe { background: var(--safe-bg); border-color: var(--safe-border); color: var(--safe-text); }\n    .verdict-box.warn { background: var(--warn-bg); border-color: var(--warn-border); color: var(--warn-text); }\n    .verdict-title { font-size: 20px; font-weight: 800; margin: 0 0 6px; }\n    .verdict-sub { margin: 0; font-size: 14px; }\n\n    .beat-static {\n      background: var(--blue-bg); border: 1px solid var(--blue-border); color: var(--blue-text);\n      border-radius: 10px; padding: 10px 13px; font-size: 13px; font-weight: 600; margin-bottom: 14px;\n    }\n\n    .meter-wrap { margin: 14px 0 18px; }\n    .meter-label { display: flex; justify-content: space-between; font-size: 13px; font-weight: 600; margin-bottom: 6px; }\n    .meter-track { height: 10px; background: #e5e7eb; border-radius: 999px; overflow: hidden; }\n    .meter-fill { height: 100%; border-radius: 999px; transition: width 0.25s ease; }\n\n    .reason-list { margin: 8px 0 16px; padding-left: 18px; font-size: 14px; }\n    .reason-list li { margin-bottom: 6px; }\n    .action-box { background: #f9fafb; border: 1px solid var(--border); border-radius: 10px; padding: 12px 14px; font-size: 14px; margin-bottom: 14px; }\n\n    details { font-size: 13px; color: var(--muted); }\n    summary { cursor: pointer; font-weight: 600; }\n    .tech-grid {\n      display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 10px;\n      background: #f9fafb; padding: 12px; border-radius: 10px; border: 1px solid var(--border);\n      font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; color: var(--text);\n    }\n    .raw-json {\n      margin: 10px 0 0; padding: 10px; background: #111827; color: #e5e7eb;\n      border-radius: 8px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n      font-size: 11px; overflow-x: auto; max-height: 180px;\n    }\n\n    .dropzone {\n      border: 2px dashed #cbd5e1; border-radius: var(--radius); padding: 34px 20px;\n      text-align: center; background: #f9fafb; cursor: pointer; transition: all 0.15s;\n    }\n    .dropzone:hover, .dropzone.drag { border-color: #111827; background: #f1f5f9; }\n    .progress-wrap { display: none; margin-top: 14px; }\n    .progress-wrap.show { display: block; }\n    .progress-track { height: 8px; background: #e5e7eb; border-radius: 999px; overflow: hidden; margin-top: 6px; }\n    .progress-fill { height: 100%; width: 0%; background: #111827; transition: width 0.15s ease; }\n\n    .stats-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-bottom: 18px; }\n    @media (max-width: 560px) { .stats-row { grid-template-columns: 1fr; } }\n    .stat-card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 16px; }\n    .stat-label { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; }\n    .stat-num { font-size: 26px; font-weight: 800; margin-top: 4px; }\n\n    .toolbar { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; margin-bottom: 14px; }\n    .search-input { max-width: 280px; padding: 8px 12px; font-size: 13px; }\n\n    table { width: 100%; border-collapse: collapse; font-size: 13px; }\n    th, td { text-align: left; padding: 10px 9px; border-bottom: 1px solid var(--border); vertical-align: middle; }\n    th { font-size: 11px; text-transform: uppercase; color: var(--muted); background: #f9fafb; white-space: nowrap; }\n    .table-wrap { overflow-x: auto; }\n    .badge { display: inline-block; padding: 3px 9px; border-radius: 999px; font-size: 12px; font-weight: 700; white-space: nowrap; }\n    .badge.safe { background: var(--safe-bg); color: var(--safe-text); }\n    .badge.warn { background: var(--warn-bg); color: var(--warn-text); }\n    .acct-link {\n      background: none; border: none; padding: 0; color: #1d4ed8; font-weight: 600;\n      font-size: 13px; cursor: pointer; text-decoration: underline; text-underline-offset: 2px;\n    }\n    .acct-link:hover { color: #1e3a8a; }\n    .btn-sm {\n      padding: 5px 9px; font-size: 12px; border-radius: 7px; border: 1px solid var(--border);\n      background: #fff; cursor: pointer; font-weight: 600; margin-right: 4px; margin-bottom: 3px;\n    }\n    .btn-sm:hover { background: #f3f4f6; }\n\n    .modal-bg {\n      position: fixed; inset: 0; background: rgba(17,24,39,0.45);\n      display: none; align-items: center; justify-content: center; padding: 20px; z-index: 50;\n    }\n    .modal-bg.open { display: flex; }\n    .modal {\n      background: #fff; border-radius: var(--radius); max-width: 580px; width: 100%;\n      max-height: 90vh; overflow-y: auto;\n      padding: 22px; box-shadow: 0 20px 40px rgba(0,0,0,0.18);\n    }\n    .modal-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }\n    .modal-head h3 { margin: 0; font-size: 17px; }\n    .modal-tabs { display: flex; gap: 6px; margin-bottom: 16px; border-bottom: 1px solid var(--border); padding-bottom: 10px; }\n    .modal-tab {\n      border: 1px solid var(--border); background: #f9fafb; color: var(--muted);\n      padding: 7px 14px; border-radius: 8px; font-size: 13px; font-weight: 600; cursor: pointer;\n    }\n    .modal-tab.active { background: #111827; color: #fff; border-color: #111827; }\n    .modal-pane { display: none; }\n    .modal-pane.active { display: block; }\n    .msg { font-size: 13px; margin-top: 10px; font-weight: 600; }\n\n    .speed-grid {\n      display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 12px;\n    }\n    @media (max-width: 520px) { .speed-grid { grid-template-columns: 1fr 1fr; } }\n    .speed-box { background: #f9fafb; border: 1px solid var(--border); border-radius: 10px; padding: 10px; }\n    .speed-box .k { font-size: 11px; color: var(--muted); text-transform: uppercase; font-weight: 600; }\n    .speed-box .v { font-size: 16px; font-weight: 800; margin-top: 2px; }\n\n    /* Account Slide-Over Drawer */\n    .drawer-bg {\n      position: fixed; inset: 0; background: rgba(17,24,39,0.4);\n      display: none; justify-content: flex-end; z-index: 60;\n    }\n    .drawer-bg.open { display: flex; }\n    .drawer {\n      background: #fff; width: 100%; max-width: 480px; height: 100%; overflow-y: auto;\n      padding: 22px; box-shadow: -10px 0 30px rgba(0,0,0,0.15);\n    }\n    .drawer-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 14px 0 18px; }\n    .drawer-stat { background: #f9fafb; border: 1px solid var(--border); border-radius: 10px; padding: 10px; }\n    .drawer-stat .k { font-size: 11px; color: var(--muted); text-transform: uppercase; font-weight: 600; }\n    .drawer-stat .v { font-size: 16px; font-weight: 800; margin-top: 2px; }\n    .timeline-item {\n      border: 1px solid var(--border); border-radius: 10px; padding: 12px; margin-bottom: 10px; font-size: 13px;\n    }\n    .timeline-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-bottom: 4px; }\n\n    footer {\n      text-align: center; padding: 18px 20px; font-size: 12px; color: var(--muted);\n      border-top: 1px solid var(--border); background: var(--card);\n    }\n\n    .tour-highlight {\n      outline: 3px solid #2563eb !important;\n      outline-offset: 4px;\n      border-radius: 12px;\n      transition: outline 0.2s ease;\n    }\n    .tour-card {\n      position: fixed;\n      bottom: 22px;\n      right: 22px;\n      width: min(390px, calc(100vw - 32px));\n      background: #111827;\n      color: #ffffff;\n      border-radius: 14px;\n      padding: 18px 20px;\n      box-shadow: 0 18px 40px rgba(0, 0, 0, 0.28);\n      z-index: 80;\n      display: none;\n      animation: fadeIn 0.18s ease;\n    }\n    .tour-card.open { display: block; }\n    .tour-step {\n      font-size: 11px;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.06em;\n      color: #93c5fd;\n      margin-bottom: 4px;\n    }\n    .tour-card h4 { margin: 0 0 6px; font-size: 16px; color: #fff; }\n    .tour-card p { margin: 0 0 14px; font-size: 13px; color: #d1d5db; line-height: 1.5; }\n    .tour-actions { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; }\n    .tour-btn {\n      padding: 7px 13px; border-radius: 8px; font-size: 12px; font-weight: 600;\n      cursor: pointer; border: 1px solid #374151; background: #1f2937; color: #fff;\n    }\n    .tour-btn:hover { background: #374151; }\n    .tour-btn.primary { background: #2563eb; border-color: #2563eb; }\n    .tour-btn.primary:hover { background: #1d4ed8; }\n    .tour-btn.skip { background: transparent; border-color: transparent; color: #9ca3af; padding-left: 0; }\n    .tour-btn.skip:hover { color: #fff; }\n\n\n    .btn-tour {\n      background: #2563eb; border: 1px solid #2563eb; color: #fff;\n      padding: 8px 14px; border-radius: 10px; font-size: 13px; font-weight: 600;\n      cursor: pointer; transition: background 0.15s;\n    }\n    .btn-tour:hover { background: #1d4ed8; }\n    .welcome-banner {\n      background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 12px;\n      padding: 13px 16px; margin-bottom: 18px;\n      display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;\n    }\n    .welcome-banner p { margin: 0; font-size: 13.5px; color: #1e3a8a; }\n    .welcome-actions { display: flex; align-items: center; gap: 8px; }\n    .welcome-close {\n      background: transparent; border: none; color: #6b7280; font-size: 18px;\n      line-height: 1; cursor: pointer; padding: 4px 6px;\n    }\n    .welcome-close:hover { color: #111827; }\n\n  </style>\n</head>\n<body>\n  <header class="topbar">\n    <div class="brand">\n      <div class="logo">AG</div>\n      <div>\n        <h1>Anomaly Guard</h1>\n        <p>Simple Mobile Money Fraud Checker</p>\n      </div>\n    </div>\n    <div class="top-actions">\n      <span id="statusPill" class="pill">Ready</span>\n      <button class="btn-tour" onclick="startTour()">Guided Demo</button>\n      <button class="btn-ghost" onclick="openSettings()">Settings</button>\n    </div>\n  </header>\n\n  <div id="wakeBanner" class="wake-banner">\n    Waking up the server &mdash; free hosting can take a few seconds on the first visit.\n  </div>\n\n  <main class="container">\n    <div id="welcomeBanner" class="welcome-banner">\n      <p><strong>New to Anomaly Guard?</strong> Follow a quick 4-step interactive demo to see how to check transfers, upload CSVs, and review alerts.</p>\n      <div class="welcome-actions">\n        <button class="btn-tour" onclick="startTour()">Start Guided Demo</button>\n        <button class="welcome-close" title="Dismiss" onclick="document.getElementById(\'welcomeBanner\').style.display=\'none\'">&times;</button>\n      </div>\n    </div>\n\n    <nav class="tabs">\n      <button class="tab active" onclick="switchTab(\'check\', this)">Check a Transfer</button>\n      <button class="tab" onclick="switchTab(\'upload\', this)">Upload CSV File</button>\n      <button class="tab" onclick="switchTab(\'history\', this)">History</button>\n    </nav>\n\n    <!-- TAB 1: CHECK A TRANSFER -->\n    <section id="tab-check" class="panel active">\n      <div class="grid-2">\n        <div class="card">\n          <h2>Enter Transfer Details</h2>\n          <p class="subtitle">Fill in the transfer below, or click an example to see Anomaly Guard in action.</p>\n\n          <div class="examples-label">Try a quick example</div>\n          <div class="examples">\n            <button type="button" class="example-btn" onclick="runExample(\'normal\')">Normal Payment (KES 250)</button>\n            <button type="button" class="example-btn" onclick="runExample(\'drain\')">Late-Night Drain (KES 185,000)</button>\n            <button type="button" class="example-btn" onclick="runExample(\'burst\')">Rapid Small Transfers (6 &times; KES 900)</button>\n            <button type="button" class="example-btn" onclick="runExample(\'mule\')">3 People Sending to 1 Account</button>\n          </div>\n\n          <form id="checkForm" onsubmit="handleCheck(event)">\n            <div class="form-grid">\n              <div class="field">\n                <label for="txType">Transaction Type</label>\n                <select id="txType">\n                  <option value="PAYMENT">Pay Till / Bill</option>\n                  <option value="TRANSFER">Send Money</option>\n                  <option value="CASH_OUT">Withdraw at Agent</option>\n                </select>\n              </div>\n              <div class="field">\n                <label for="amount">Amount (KES)</label>\n                <input id="amount" type="number" step="0.01" min="1" value="250.50" required oninput="onAmountOrOldChange()" />\n              </div>\n              <div class="field">\n                <label for="oldBalance">Balance Before (KES)</label>\n                <input id="oldBalance" type="number" step="0.01" min="0" value="12500" required oninput="onAmountOrOldChange()" />\n              </div>\n              <div class="field">\n                <label for="newBalance">Balance After (KES)</label>\n                <input id="newBalance" type="number" step="0.01" min="0" value="12249.50" required oninput="onNewBalanceManualEdit()" />\n              </div>\n              <div class="field full">\n                <div id="mathHint" class="math-hint ok"><span>Balances match</span></div>\n              </div>\n              <div class="field">\n                <label for="sender">Sender Account</label>\n                <input id="sender" type="text" value="USER-001" required />\n              </div>\n              <div class="field">\n                <label for="recipient">Recipient / Till</label>\n                <input id="recipient" type="text" value="TILL-NAIVAS" required />\n              </div>\n              <div class="field full">\n                <label for="txTime">Time of Transfer</label>\n                <select id="txTime">\n                  <option value="day">Now (Daytime)</option>\n                  <option value="night">Late Night (2:30 AM)</option>\n                </select>\n              </div>\n            </div>\n            <button id="checkBtn" class="btn-primary" type="submit">Check Transaction</button>\n          </form>\n        </div>\n\n        <div class="card">\n          <h2>Result</h2>\n          <div id="resultArea" class="result-empty">\n            Fill in the transfer details on the left and click <strong>Check Transaction</strong>, or pick one of the quick examples above.\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 2: UPLOAD CSV -->\n    <section id="tab-upload" class="panel">\n      <div class="card">\n        <div class="toolbar">\n          <div>\n            <h2 style="margin:0;">Check Multiple Transactions from a CSV File</h2>\n            <p class="subtitle" style="margin:4px 0 0;">Upload a spreadsheet exported as CSV to check every transfer at once.</p>\n          </div>\n          <div style="display:flex; gap:8px; flex-wrap:wrap;">\n            <button class="btn-ghost" type="button" onclick="downloadSampleCsv()">Download Sample CSV</button>\n            <button id="downloadCheckedBtn" class="btn-ghost" type="button" style="display:none;" onclick="downloadCheckedCsv()">Download Checked CSV</button>\n          </div>\n        </div>\n\n        <div id="dropzone" class="dropzone" onclick="document.getElementById(\'csvInput\').click()">\n          <p style="margin:0 0 6px; font-weight:700; font-size:15px;">Click to choose a CSV file, or drag and drop it here</p>\n          <p style="margin:0; font-size:13px; color:var(--muted);">Columns supported: type, amount, sender, recipient, balance_before, balance_after, time</p>\n          <input id="csvInput" type="file" accept=".csv,text/csv" style="display:none;" onchange="handleCsvFile(this.files[0])" />\n        </div>\n\n        <div id="upProgressWrap" class="progress-wrap">\n          <div id="uploadStatus" style="font-size:13px; font-weight:600;"></div>\n          <div class="progress-track"><div id="upProgressFill" class="progress-fill"></div></div>\n        </div>\n\n        <div id="uploadSummary" style="display:none; margin-top:18px;">\n          <div class="stats-row">\n            <div class="stat-card"><div class="stat-label">Checked</div><div id="upTotal" class="stat-num">0</div></div>\n            <div class="stat-card"><div class="stat-label">Safe</div><div id="upSafe" class="stat-num" style="color:var(--safe-text);">0</div></div>\n            <div class="stat-card"><div class="stat-label">Flagged</div><div id="upFlagged" class="stat-num" style="color:var(--warn-text);">0</div></div>\n          </div>\n          <div class="table-wrap">\n            <table>\n              <thead><tr><th>#</th><th>Type</th><th>Amount (KES)</th><th>Accounts</th><th>Status</th><th>Risk</th><th>Reason</th></tr></thead>\n              <tbody id="uploadRows"></tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 3: HISTORY -->\n    <section id="tab-history" class="panel">\n      <div class="stats-row">\n        <div class="stat-card"><div class="stat-label">Total Checked</div><div id="histTotal" class="stat-num">0</div></div>\n        <div class="stat-card"><div class="stat-label">Safe</div><div id="histSafe" class="stat-num" style="color:var(--safe-text);">0</div></div>\n        <div class="stat-card"><div class="stat-label">Flagged</div><div id="histFlagged" class="stat-num" style="color:var(--warn-text);">0</div></div>\n      </div>\n\n      <div class="card">\n        <div class="toolbar">\n          <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap; flex:1;">\n            <button id="filterAll" class="btn-ghost active-filter" onclick="setHistoryFilter(\'all\')">Show All</button>\n            <button id="filterFlagged" class="btn-ghost" onclick="setHistoryFilter(\'flagged\')">Flagged Only</button>\n            <input id="historySearch" class="search-input" type="search" placeholder="Search account, type, or amount..." oninput="renderHistoryTable()" />\n          </div>\n          <div style="display:flex; gap:8px;">\n            <button class="btn-ghost" onclick="loadHistory()">Refresh</button>\n            <a class="btn-ghost" href="/export/csv">Download CSV</a>\n          </div>\n        </div>\n        <div class="table-wrap">\n          <table>\n            <thead><tr><th>Time</th><th>Type</th><th>Amount (KES)</th><th>Accounts</th><th>Status</th><th>Reason</th><th>Feedback</th></tr></thead>\n            <tbody id="historyRows">\n              <tr><td colspan="7" style="text-align:center; color:var(--muted); padding:26px;">No transactions checked yet.</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n  </main>\n\n\n  <!-- SIMPLE INTERACTIVE QUICK TOUR -->\n  <div id="tourCard" class="tour-card" role="dialog" aria-label="Quick Tour">\n    <div id="tourStepLabel" class="tour-step">Step 1 of 4</div>\n    <h4 id="tourTitle">Check a Transfer</h4>\n    <p id="tourBody"></p>\n    <div class="tour-actions">\n      <button class="tour-btn skip" onclick="endTour()">Skip Tour</button>\n      <div style="display:flex; gap:6px;">\n        <button id="tourBackBtn" class="tour-btn" onclick="prevTourStep()">Back</button>\n        <button id="tourDemoBtn" class="tour-btn" style="display:none;" onclick="runTourDemo()">Try Live Example</button>\n        <button id="tourNextBtn" class="tour-btn primary" onclick="nextTourStep()">Next</button>\n      </div>\n    </div>\n  </div>\n\n  <footer>\n    Demo mode using synthetic data only &mdash; compliant with the Kenya Data Protection Act (2019).\n  </footer>\n\n  <!-- SETTINGS & PERFORMANCE MODAL (TUCKED AWAY FOR ADMIN / EXAMINER) -->\n  <div id="settingsModal" class="modal-bg" onclick="if(event.target===this) closeSettings()">\n    <div class="modal">\n      <div class="modal-head">\n        <h3>Settings &amp; System Info</h3>\n        <button class="btn-ghost" onclick="closeSettings()">Close</button>\n      </div>\n\n      <div class="modal-tabs">\n        <button id="mtab-controls" class="modal-tab active" onclick="switchModalTab(\'controls\')">Admin Controls</button>\n        <button id="mtab-perf" class="modal-tab" onclick="switchModalTab(\'perf\')">Performance &amp; API</button>\n      </div>\n\n      <!-- PANE 1: ADMIN CONTROLS -->\n      <div id="mpane-controls" class="modal-pane active">\n        <div class="field" style="margin-bottom:14px;">\n          <label>Alert Sensitivity Cutoff: <strong id="cutoffVal">0.20</strong></label>\n          <input id="cutoffSlider" type="range" min="0.10" max="0.90" step="0.05" value="0.20"\n                 oninput="document.getElementById(\'cutoffVal\').textContent = Number(this.value).toFixed(2)" />\n          <div style="display:flex; justify-content:space-between; font-size:12px; color:var(--muted);">\n            <span>More Alerts (Strict)</span><span>Fewer Alerts (Relaxed)</span>\n          </div>\n        </div>\n        <div class="field" style="margin-bottom:14px;">\n          <label for="adminPin">Admin PIN (demo default: 2026)</label>\n          <input id="adminPin" type="password" value="2026" />\n        </div>\n        <div style="display:flex; gap:8px;">\n          <button class="btn-primary" style="margin-top:0;" onclick="saveCutoff()">Save Sensitivity</button>\n          <button class="btn-ghost" style="color:var(--warn-text); border-color:var(--warn-border);" onclick="clearHistory()">Clear History</button>\n        </div>\n        <div id="settingsMsg" class="msg"></div>\n      </div>\n\n      <!-- PANE 2: PERFORMANCE & API -->\n      <div id="mpane-perf" class="modal-pane">\n        <div style="font-size:13px; font-weight:700; margin-bottom:8px;">Offline Model Comparison (Unseen PaySim Holdout)</div>\n        <div class="table-wrap" style="margin-bottom:16px;">\n          <table>\n            <thead><tr><th>Method</th><th>F1</th><th>Precision</th><th>Recall</th><th>False Alarms</th></tr></thead>\n            <tbody id="benchRows">\n              <tr><td colspan="5" style="color:var(--muted);">Loading model metrics...</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div style="display:flex; justify-content:space-between; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:8px;">\n          <div>\n            <div style="font-size:13px; font-weight:700;">Live Speed Test (20 Concurrent Checks)</div>\n            <div style="font-size:12px; color:var(--muted);">Verifies end-to-end response stays within the 1,500 ms SLA.</div>\n          </div>\n          <button id="speedBtn" class="btn-ghost" onclick="runSpeedTest()">Run 20-Request Test</button>\n        </div>\n        <div id="speedOut"></div>\n\n        <div style="margin-top:16px; padding-top:12px; border-top:1px solid var(--border); display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">\n          <span style="font-size:12px; color:var(--muted);">Developer REST API specification</span>\n          <a class="btn-ghost" href="/docs" target="_blank" rel="noopener">Open API Docs (/docs)</a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ACCOUNT TIMELINE DRAWER -->\n  <div id="accountDrawer" class="drawer-bg" onclick="if(event.target===this) closeAccountDrawer()">\n    <div class="drawer">\n      <div class="modal-head">\n        <div>\n          <h3 id="drawerTitle" style="margin:0;">Account Activity</h3>\n          <div style="font-size:12px; color:var(--muted);">Recent transfers sent or received by this account</div>\n        </div>\n        <button class="btn-ghost" onclick="closeAccountDrawer()">Close</button>\n      </div>\n      <div id="drawerBody" style="font-size:14px; color:var(--muted);">Loading activity...</div>\n    </div>\n  </div>\n\n  <script>\n    const SCHEMA = {"score": {"tx_id": "tx_id", "tx_type": "tx_type", "amount": "amount_kes", "sender": "origin_account_id", "recipient": "vendor_hash", "old_orig": "oldbalance_org", "new_orig": "newbalance_orig", "old_dest": "oldbalance_dest", "new_dest": "newbalance_dest", "timestamp": "timestamp"}, "threshold_key": "threshold", "disposition_key": "review_status"};\n    let historyCache = [];\n    let historyFilter = \'all\';\n    let autoSyncBalance = true;\n    let lastCheckedCsv = { headers: [], rows: [] };\n\n    function switchTab(name, btn) {\n      document.querySelectorAll(\'.panel\').forEach(p => p.classList.remove(\'active\'));\n      document.querySelectorAll(\'.tab\').forEach(t => t.classList.remove(\'active\'));\n      document.getElementById(\'tab-\' + name).classList.add(\'active\');\n      if (btn) btn.classList.add(\'active\');\n      if (name === \'history\') loadHistory();\n    }\n\n    function switchModalTab(name) {\n      document.querySelectorAll(\'.modal-tab\').forEach(b => b.classList.remove(\'active\'));\n      document.querySelectorAll(\'.modal-pane\').forEach(p => p.classList.remove(\'active\'));\n      document.getElementById(\'mtab-\' + name).classList.add(\'active\');\n      document.getElementById(\'mpane-\' + name).classList.add(\'active\');\n      if (name === \'perf\') loadBenchmarks();\n    }\n\n    function escapeHtml(s) {\n      return String(s ?? \'\').replace(/[&<>"\']/g, c => ({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\n    }\n\n    function fmtKes(n) {\n      return \'KES \' + Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n    }\n\n    function friendlyType(t) {\n      const u = String(t || \'\').toUpperCase();\n      if (u === \'PAYMENT\') return \'Pay Till / Bill\';\n      if (u === \'TRANSFER\') return \'Send Money\';\n      if (u === \'CASH_OUT\') return \'Agent Cash-Out\';\n      return u || \'Transfer\';\n    }\n\n    function onAmountOrOldChange() {\n      const amt = Number(document.getElementById(\'amount\').value || 0);\n      const oldB = Number(document.getElementById(\'oldBalance\').value || 0);\n      if (autoSyncBalance) {\n        document.getElementById(\'newBalance\').value = Math.max(0, Number((oldB - amt).toFixed(2)));\n      }\nupdateBalanceHint();\n    }\n\n    function onNewBalanceManualEdit() {\n      autoSyncBalance = false;\n      updateBalanceHint();\n    }\n\n    function fixBalance() {\n      autoSyncBalance = true;\n      onAmountOrOldChange();\n    }\n\n    function updateBalanceHint() {\n      const amt = Number(document.getElementById(\'amount\').value || 0);\n      const oldB = Number(document.getElementById(\'oldBalance\').value || 0);\n      const newB = Number(document.getElementById(\'newBalance\').value || 0);\n      const hint = document.getElementById(\'mathHint\');\n      if (oldB > 0 && amt > oldB) {\n        hint.className = \'math-hint warn\';\n        hint.innerHTML = `<span>Amount is higher than Balance Before (overdraft).</span>`;\n        return;\n      }\n      const expected = Math.max(0, oldB - amt);\n      const diff = Math.abs(newB - expected);\n      if (diff <= 1.0) {\n        hint.className = \'math-hint ok\';\n        hint.innerHTML = `<span>Balances match (${fmtKes(oldB)} &minus; ${fmtKes(amt)} = ${fmtKes(expected)})</span>`;\n      } else {\n        hint.className = \'math-hint warn\';\n        hint.innerHTML = `<span>Balance After is off by ${fmtKes(diff)}</span><button type="button" class="link-btn" onclick="fixBalance()">Auto-fix</button>`;\n      }\n    }\n\n    function makeTxId(prefix) {\n      return (prefix || \'TX\') + \'-\' + Date.now().toString(36).toUpperCase() + \'-\' + Math.random().toString(36).slice(2, 6).toUpperCase();\n    }\n\n    function buildIsoTime(mode, offsetMinutes) {\n      const d = new Date();\n      if (mode === \'night\') d.setHours(2, 30 + (offsetMinutes || 0), 0, 0);\n      else if (offsetMinutes) d.setMinutes(d.getMinutes() + offsetMinutes);\n      return d.toISOString();\n    }\n\n    function buildPayload({ txId, txType, amount, sender, recipient, oldOrig, newOrig, oldDest, newDest, timestamp }) {\n      const s = SCHEMA.score;\n      const p = {};\n      p[s.tx_id] = txId || makeTxId(\'TX\');\n      p[s.tx_type] = txType || \'PAYMENT\';\n      p[s.amount] = Number(amount);\n      p[s.sender] = sender || \'USER-001\';\n      p[s.recipient] = recipient || \'TILL-NAIVAS\';\n      p[s.old_orig] = Number(oldOrig);\n      p[s.new_orig] = Number(newOrig);\n      p[s.old_dest] = Number(oldDest || 0);\n      p[s.new_dest] = Number(newDest != null ? newDest : Number(oldDest || 0) + Number(amount));\n      p[s.timestamp] = timestamp || new Date().toISOString();\n      return p;\n    }\n\n    function extractVerdict(data) {\n      const score = Number(data.anomaly_score ?? data.score ?? data.risk_score ?? 0);\n      const cutoff = Number(data.threshold_used ?? data.threshold ?? 0.20);\n      const rawVerdict = data.binary_verdict ?? data.verdict;\n      const flagged = rawVerdict !== undefined ? Boolean(Number(rawVerdict)) : score >= cutoff;\n      let reasons = data.signals ?? data.triggering_features ?? data.reasons ?? [];\n      if (typeof reasons === \'string\') {\n        try { reasons = JSON.parse(reasons); } catch { reasons = reasons ? [reasons] : []; }\n      }\n      if (!Array.isArray(reasons)) reasons = [];\n      return { score, cutoff, flagged, reasons };\n    }\n\n    function translateSignal(raw) {\n      const s = String(raw || \'\').trim();\n      const low = s.toLowerCase();\n      if (low.includes(\'smurf\') || (low.includes(\'velocity\') && low.includes(\'15\'))) {\n        return \'Several small transfers were sent from this account within a few minutes (possible split-transfer structuring).\';\n      }\n      if (low.includes(\'fan-in\') || low.includes(\'fan_in\') || low.includes(\'mule\') || low.includes(\'distinct senders\') || low.includes(\'other senders\')) {\n        return \'Multiple different people sent money into this same account within 15 minutes (common mule-account pattern).\';\n      }\n      if (low.includes(\'ghost\') && (low.includes(\'drain\') || low.includes(\'empty\') || low.includes(\'zero\'))) {\n        return \'The entire account balance was emptied during late-night hours.\';\n      }\n      if (low.includes(\'full-balance\') || low.includes(\'full balance\') || low.includes(\'balance drain\') || low.includes(\'empties\')) {\n        return \'A large transfer emptied the sender\\\'s entire balance down to KES 0.\';\n      }\n      if (low.includes(\'overdraft\') || low.includes(\'exceeds\')) {\n        return \'The transfer amount is larger than the sender\\\'s available balance.\';\n      }\n      if (low.includes(\'ledger\') || low.includes(\'mismatch\') || low.includes(\'reconcil\')) {\n        return \'The balance before and after this transfer do not add up properly.\';\n      }\n      if (low.includes(\'ghost\') || low.includes(\'overnight\') || low.includes(\'00:00\')) {\n        return \'Large transfer made during unusual late-night hours (midnight to 5:00 AM).\';\n      }\n      if (low.includes(\'within normal baseline\') || low.includes(\'baseline\')) {\n        return \'Amount, timing, and account balances all match normal everyday activity.\';\n      }\n      return s.replace(/\\[.*?\\]\\s*/g, \'\').replace(/_/g, \' \').trim();\n    }\n\n    function plainReasons(reasons, flagged) {\n      if (!reasons || !reasons.length) {\n        return flagged\n          ? [\'Unusual transfer pattern detected compared to normal mobile money activity.\']\n          : [\'Amount, timing, and account balances all look normal.\'];\n      }\n      const unique = [];\n      reasons.forEach(r => {\n        const t = translateSignal(r);\n        if (t && !unique.includes(t)) unique.push(t);\n      });\n      return unique.length ? unique : (flagged ? [\'Suspicious activity pattern detected.\'] : [\'Looks normal.\']);\n    }\n\n    function renderResult(data, note, amountKes) {\n      const { score, cutoff, flagged, reasons } = extractVerdict(data);\n      const pct = Math.min(100, Math.max(0, Math.round(score * 100)));\n      const cleanReasons = plainReasons(reasons, flagged);\n      const riskWord = pct >= 70 ? \'High\' : pct >= 25 ? \'Medium\' : \'Low\';\n      const fillColor = flagged ? \'#dc2626\' : \'#059669\';\n      const actionText = flagged\n        ? \'Pause this transfer and verify directly with the account holder before releasing funds.\'\n        : \'This transfer looks normal and safe to proceed.\';\n      const amt = Number(amountKes ?? data.amount_kes ?? data.amount ?? 0);\n      const staticFlagged = data.static_rule_verdict !== undefined ? Boolean(Number(data.static_rule_verdict)) : amt > 50000;\n      const staticMissed = flagged && !staticFlagged;\n      const staticLabel = staticFlagged ? \'FLAGGED (> 50k)\' : (flagged ? \'MISSED (< 50k)\' : \'CLEARED\');\n      const mlVal = data.ml_score != null ? Number(data.ml_score).toFixed(2) : \'—\';\n      const polVal = data.policy_score != null ? Number(data.policy_score).toFixed(2) : \'—\';\n      const latVal = data.latency_ms != null ? Number(data.latency_ms).toFixed(1) + \' ms\' : \'—\';\n      const srcVal = data.scoring_source || \'—\';\n\n      document.getElementById(\'resultArea\').className = \'\';\n      document.getElementById(\'resultArea\').innerHTML = `\n        <div class="verdict-box ${flagged ? \'warn\' : \'safe\'}">\n          <div class="verdict-title">${flagged ? \'WARNING &mdash; Possible Fraud\' : \'SAFE &mdash; Looks Normal\'}</div>\n          <p class="verdict-sub">${escapeHtml(note || (flagged ? \'This transaction was flagged for review.\' : \'No suspicious behaviour found.\'))}</p>\n        </div>\n\n        ${staticMissed ? \'<div class="beat-static">Caught even though it is under KES 50,000 &mdash; standard static bank limits would have let this through.</div>\' : \'\'}\n\n        <div class="meter-wrap">\n          <div class="meter-label"><span>Risk Level: ${riskWord}</span><span>${pct}%</span></div>\n          <div class="meter-track"><div class="meter-fill" style="width:${Math.max(pct, 3)}%; background:${fillColor};"></div></div>\n        </div>\n\n        <div style="font-size:13px; font-weight:700; color:#374151;">Why:</div>\n        <ul class="reason-list">${cleanReasons.map(r => `<li>${escapeHtml(r)}</li>`).join(\'\')}</ul>\n\n        <div class="action-box"><strong>What to do:</strong> ${actionText}</div>\n\n        <details>\n          <summary>Show technical details</summary>\n          <div class="tech-grid">\n            <div>ML Score: ${mlVal}</div>\n            <div>Policy Score: ${polVal}</div>\n            <div>Source: ${escapeHtml(srcVal)}</div>\n            <div>Static Rule: ${escapeHtml(staticLabel)}</div>\n            <div>Cutoff: ${cutoff.toFixed(2)}</div>\n            <div>Server Speed: ${latVal}</div>\n          </div>\n          <pre class="raw-json">${escapeHtml(JSON.stringify(data, null, 2))}</pre>\n        </details>\n      `;\n    }\n\n    async function scoreOne(payload) {\n      const res = await fetch(\'/score\', {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify(payload),\n      });\n      if (!res.ok) throw new Error(\'Request failed (\' + res.status + \'): \' + await res.text());\n      return await res.json();\n    }\n\n    async function handleCheck(e) {\n      e.preventDefault();\n      const btn = document.getElementById(\'checkBtn\');\n      btn.disabled = true; btn.textContent = \'Checking...\';\n      try {\n        const txType = document.getElementById(\'txType\').value;\n        const amount = Number(document.getElementById(\'amount\').value);\n        const oldOrig = Number(document.getElementById(\'oldBalance\').value);\n        const newOrig = Number(document.getElementById(\'newBalance\').value);\n        const payload = buildPayload({\n          txType, amount,\n          sender: document.getElementById(\'sender\').value.trim(),\n          recipient: document.getElementById(\'recipient\').value.trim(),\n          oldOrig, newOrig,\n          timestamp: buildIsoTime(document.getElementById(\'txTime\').value, 0),\n        });\n        renderResult(await scoreOne(payload), null, amount);\n      } catch (err) {\n        document.getElementById(\'resultArea\').innerHTML = `<div class="verdict-box warn"><div class="verdict-title">Could not check transfer</div><p class="verdict-sub">${escapeHtml(err.message)}</p></div>`;\n      } finally {\n        btn.disabled = false; btn.textContent = \'Check Transaction\';\n      }\n    }\n\n    async function runExample(kind) {\n      autoSyncBalance = true;\n      const btn = document.getElementById(\'checkBtn\');\n      if (kind === \'normal\') {\n        document.getElementById(\'txType\').value = \'PAYMENT\';\n        document.getElementById(\'amount\').value = \'250.50\';\n        document.getElementById(\'oldBalance\').value = \'12500\';\n        document.getElementById(\'txTime\').value = \'day\';\n        document.getElementById(\'sender\').value = \'USER-001\';\n        document.getElementById(\'recipient\').value = \'TILL-NAIVAS\';\n        onAmountOrOldChange();\n        document.getElementById(\'checkForm\').requestSubmit();\n      } else if (kind === \'drain\') {\n        document.getElementById(\'txType\').value = \'CASH_OUT\';\n        document.getElementById(\'amount\').value = \'185000\';\n        document.getElementById(\'oldBalance\').value = \'185000\';\n        document.getElementById(\'txTime\').value = \'night\';\n        document.getElementById(\'sender\').value = \'USER-VICTIM-09\';\n        document.getElementById(\'recipient\').value = \'AGENT-4421\';\n        onAmountOrOldChange();\n        document.getElementById(\'checkForm\').requestSubmit();\n      } else if (kind === \'burst\') {\n        const senderId = \'USER-BURST-\' + Math.random().toString(36).slice(2, 5).toUpperCase();\n        document.getElementById(\'txType\').value = \'TRANSFER\';\n        document.getElementById(\'amount\').value = \'900\';\n        document.getElementById(\'oldBalance\').value = \'15000\';\n        document.getElementById(\'txTime\').value = \'day\';\n        document.getElementById(\'sender\').value = senderId;\n        document.getElementById(\'recipient\').value = \'WALLET-MULE-07\';\n        onAmountOrOldChange();\n        btn.disabled = true; btn.textContent = \'Sending 6 rapid transfers...\';\n        try {\n          let bal = 15000, lastData = null;\n          for (let i = 0; i < 6; i++) {\n            const nextBal = bal - 900;\n            lastData = await scoreOne(buildPayload({\n              txId: makeTxId(\'BURST\' + (i + 1)), txType: \'TRANSFER\', amount: 900,\n              sender: senderId, recipient: \'WALLET-MULE-07\', oldOrig: bal, newOrig: nextBal,\n              timestamp: buildIsoTime(\'day\', i - 5),\n            }));\n            bal = nextBal;\n          }\n          renderResult(lastData, \'Sent 6 rapid KES 900 transfers in a few minutes from the same account.\', 900);\n        } catch (err) {\n          document.getElementById(\'resultArea\').innerHTML = `<div class="verdict-box warn"><div class="verdict-title">Error</div><p class="verdict-sub">${escapeHtml(err.message)}</p></div>`;\n        } finally {\n          btn.disabled = false; btn.textContent = \'Check Transaction\';\n        }\n      } else if (kind === \'mule\') {\n        const tag = Math.random().toString(36).slice(2, 5).toUpperCase();\n        const muleWallet = \'WALLET-MULE-\' + tag;\n        const senders = [\'USER-VICTIM-A-\' + tag, \'USER-VICTIM-B-\' + tag, \'USER-VICTIM-C-\' + tag];\n        document.getElementById(\'txType\').value = \'TRANSFER\';\n        document.getElementById(\'amount\').value = \'18000\';\n        document.getElementById(\'oldBalance\').value = \'45000\';\n        document.getElementById(\'txTime\').value = \'day\';\n        document.getElementById(\'sender\').value = senders[2];\n        document.getElementById(\'recipient\').value = muleWallet;\n        onAmountOrOldChange();\n        btn.disabled = true; btn.textContent = \'Sending from 3 accounts...\';\n        try {\n          let lastData = null;\n          for (let i = 0; i < senders.length; i++) {\n            lastData = await scoreOne(buildPayload({\n              txId: makeTxId(\'MULE\' + (i + 1)), txType: \'TRANSFER\', amount: 18000,\n              sender: senders[i], recipient: muleWallet, oldOrig: 45000, newOrig: 27000,\n              timestamp: buildIsoTime(\'day\', i - 2),\n            }));\n          }\n          renderResult(lastData, `3 different people sent KES 18,000 into ${muleWallet} within minutes.`, 18000);\n        } catch (err) {\n          document.getElementById(\'resultArea\').innerHTML = `<div class="verdict-box warn"><div class="verdict-title">Error</div><p class="verdict-sub">${escapeHtml(err.message)}</p></div>`;\n        } finally {\n          btn.disabled = false; btn.textContent = \'Check Transaction\';\n        }\n      }\n    }\n\n    // CSV UPLOAD\n    const dz = document.getElementById(\'dropzone\');\n    dz.addEventListener(\'dragover\', e => { e.preventDefault(); dz.classList.add(\'drag\'); });\n    dz.addEventListener(\'dragleave\', () => dz.classList.remove(\'drag\'));\n    dz.addEventListener(\'drop\', e => { e.preventDefault(); dz.classList.remove(\'drag\'); if (e.dataTransfer.files[0]) handleCsvFile(e.dataTransfer.files[0]); });\n\n    function downloadSampleCsv() {\n      const sample = [\n        \'type,amount,sender,recipient,balance_before,balance_after,time\',\n        \'PAYMENT,250.50,USER-101,TILL-NAIVAS,12500,12249.50,2026-11-20T11:15:00Z\',\n        \'PAYMENT,1450.00,USER-102,TILL-JAVA,8900,7450.00,2026-11-20T13:20:00Z\',\n        \'CASH_OUT,185000,USER-103,AGENT-4421,185000,0,2026-11-20T02:30:00Z\',\n        \'PAYMENT,2500,USER-104,TILL-SHOP,12500,11000,2026-11-20T14:00:00Z\',\n        \'TRANSFER,540000,USER-105,WALLET-99,540000,0,2026-11-20T03:15:00Z\'\n      ].join(\'\\n\');\n      triggerDownload(sample, \'sample_transactions.csv\');\n    }\n\n    function triggerDownload(content, filename) {\n      const url = URL.createObjectURL(new Blob([content], { type: \'text/csv\' }));\n      const a = document.createElement(\'a\'); a.href = url; a.download = filename; a.click();\n      URL.revokeObjectURL(url);\n    }\n\n    function csvCell(v) {\n      const s = String(v ?? \'\');\n      return /[",\\n]/.test(s) ? \'"\' + s.replace(/"/g, \'""\') + \'"\' : s;\n    }\n\n    function downloadCheckedCsv() {\n      if (!lastCheckedCsv.rows.length) return;\n      const headers = [...lastCheckedCsv.headers, \'status\', \'risk_percent\', \'reason\'];\n      const lines = [headers.map(csvCell).join(\',\')];\n      lastCheckedCsv.rows.forEach(r => lines.push(headers.map(h => csvCell(r[h])).join(\',\')));\n      triggerDownload(lines.join(\'\\n\'), \'checked_transactions.csv\');\n    }\n\n    function parseCsv(text) {\n      const lines = text.trim().split(/\\r?\\n/).filter(l => l.trim());\n      if (lines.length < 2) return { headers: [], rows: [] };\n      const headers = lines[0].split(\',\').map(h => h.trim().toLowerCase().replace(/^"|"$/g, \'\'));\n      const rows = lines.slice(1).map(line => {\n        const vals = line.split(\',\').map(v => v.trim().replace(/^"|"$/g, \'\'));\n        const obj = {}; headers.forEach((h, i) => obj[h] = vals[i] ?? \'\'); return obj;\n      });\n      return { headers, rows };\n    }\n\n    async function handleCsvFile(file) {\n      if (!file) return;\n      const progWrap = document.getElementById(\'upProgressWrap\');\n      const progFill = document.getElementById(\'upProgressFill\');\n      const statusEl = document.getElementById(\'uploadStatus\');\n      const dlBtn = document.getElementById(\'downloadCheckedBtn\');\n      dlBtn.style.display = \'none\';\n      const parsed = parseCsv(await file.text());\n      const rows = parsed.rows;\n      progWrap.classList.add(\'show\');\n      if (!rows.length) {\n        statusEl.textContent = \'The file looks empty. Try downloading the sample CSV first.\';\n        progFill.style.width = \'0%\';\n        return;\n      }\n      document.getElementById(\'uploadSummary\').style.display = \'block\';\n      const tbody = document.getElementById(\'uploadRows\'); tbody.innerHTML = \'\';\n      let safe = 0, flagged = 0;\n      const outRows = [];\n\n      for (let i = 0; i < rows.length; i++) {\n        const r = rows[i];\n        statusEl.textContent = `Checking transaction ${i + 1} of ${rows.length}...`;\n        progFill.style.width = Math.round(((i + 1) / rows.length) * 100) + \'%\';\n\n        const amount = Number(r.amount || r.amount_kes || 0);\n        const oldOrig = Number(r.balance_before || r.oldbalance_org || r.oldbalanceorg || (amount + 5000));\n        const newOrig = r.balance_after !== undefined && r.balance_after !== \'\'\n          ? Number(r.balance_after)\n          : (r.newbalance_orig !== undefined && r.newbalance_orig !== \'\' ? Number(r.newbalance_orig) : Math.max(0, oldOrig - amount));\n        const txType = (r.type || r.tx_type || \'PAYMENT\').toUpperCase();\n        const sender = r.sender || r.origin_account_id || r.nameorig || (\'CSV-USER-\' + (i + 1));\n        const recipient = r.recipient || r.vendor_hash || r.namedest || \'TILL-001\';\n        const ts = r.time || r.timestamp || new Date().toISOString();\n\n        try {\n          const res = await scoreOne(buildPayload({ txId: makeTxId(\'CSV\' + (i + 1)), txType, amount, sender, recipient, oldOrig, newOrig, timestamp: ts }));\n          const v = extractVerdict(res);\n          const pct = Math.min(100, Math.max(0, Math.round(v.score * 100)));\n          const reason = plainReasons(v.reasons, v.flagged)[0] || \'\';\n          if (v.flagged) flagged++; else safe++;\n          outRows.push({ ...r, status: v.flagged ? \'FLAGGED\' : \'SAFE\', risk_percent: pct + \'%\', reason });\n          tbody.innerHTML += `<tr>\n            <td>${i + 1}</td>\n            <td>${escapeHtml(friendlyType(txType))}</td>\n            <td>${fmtKes(amount)}</td>\n            <td><button class="acct-link" onclick="openAccountDrawer(\'${escapeHtml(sender)}\')">${escapeHtml(sender)}</button> &rarr; <button class="acct-link" onclick="openAccountDrawer(\'${escapeHtml(recipient)}\')">${escapeHtml(recipient)}</button></td>\n            <td><span class="badge ${v.flagged ? \'warn\' : \'safe\'}">${v.flagged ? \'FLAGGED\' : \'SAFE\'}</span></td>\n            <td>${pct}%</td>\n            <td>${escapeHtml(reason)}</td>\n          </tr>`;\n        } catch (err) {\n          outRows.push({ ...r, status: \'ERROR\', risk_percent: \'\', reason: err.message });\n          tbody.innerHTML += `<tr><td>${i + 1}</td><td colspan="6" style="color:var(--warn-text);">${escapeHtml(err.message)}</td></tr>`;\n        }\n        document.getElementById(\'upTotal\').textContent = i + 1;\n        document.getElementById(\'upSafe\').textContent = safe;\n        document.getElementById(\'upFlagged\').textContent = flagged;\n      }\n\n      lastCheckedCsv = { headers: parsed.headers, rows: outRows };\n      statusEl.textContent = `Done! Checked ${rows.length} transactions (${flagged} flagged, ${safe} safe).`;\n      dlBtn.style.display = \'inline-block\';\n    }\n\n    // HISTORY\n    async function loadHistory() {\n      try {\n        const raw = await (await fetch(\'/transactions\')).json();\n        historyCache = Array.isArray(raw) ? raw : (raw.transactions || raw.items || []);\n        const total = historyCache.length;\n        const flagged = historyCache.filter(x => extractVerdict(x).flagged).length;\n        document.getElementById(\'histTotal\').textContent = total;\n        document.getElementById(\'histFlagged\').textContent = flagged;\n        document.getElementById(\'histSafe\').textContent = total - flagged;\n        renderHistoryTable();\n      } catch {\n        document.getElementById(\'historyRows\').innerHTML = \'<tr><td colspan="7" style="color:var(--warn-text);">Could not load history.</td></tr>\';\n      }\n    }\n\n    function setHistoryFilter(f) {\n      historyFilter = f;\n      document.getElementById(\'filterAll\').classList.toggle(\'active-filter\', f === \'all\');\n      document.getElementById(\'filterFlagged\').classList.toggle(\'active-filter\', f === \'flagged\');\n      renderHistoryTable();\n    }\n\n    function renderHistoryTable() {\n      const q = (document.getElementById(\'historySearch\')?.value || \'\').trim().toLowerCase();\n      let rows = historyFilter === \'flagged\' ? historyCache.filter(x => extractVerdict(x).flagged) : historyCache;\n      if (q) {\n        rows = rows.filter(item => {\n          const blob = [\n            item.origin_account_id, item.sender, item.vendor_hash, item.recipient,\n            item.tx_type, item.type, item.amount_kes, item.amount, item.tx_id\n          ].join(\' \').toLowerCase();\n          return blob.includes(q);\n        });\n      }\n      const tbody = document.getElementById(\'historyRows\');\n      if (!rows.length) {\n        tbody.innerHTML = \'<tr><td colspan="7" style="text-align:center; color:var(--muted); padding:26px;">No matching transactions found.</td></tr>\';\n        return;\n      }\n      tbody.innerHTML = rows.slice(0, 100).map(item => {\n        const v = extractVerdict(item);\n        const txId = item.tx_id || item.id || \'\';\n        const amt = Number(item.amount_kes ?? item.amount ?? 0);\n        const ttype = friendlyType(item.tx_type || item.type);\n        const sender = item.origin_account_id || item.sender || \'—\';\n        const recipient = item.vendor_hash || item.recipient || \'—\';\n        const ts = item.timestamp ? new Date(item.timestamp).toLocaleTimeString([], {hour:\'2-digit\', minute:\'2-digit\'}) : \'—\';\n        const reason = plainReasons(v.reasons, v.flagged)[0] || \'\';\n        const rev = item.review_status || \'PENDING\';\n        let actionCell = \'<span style="color:var(--muted);">&mdash;</span>\';\n        if (v.flagged) {\n          if (rev === \'CONFIRMED_FRAUD\') actionCell = \'<span class="badge warn">Confirmed Fraud</span>\';\n          else if (rev === \'FALSE_POSITIVE\') actionCell = \'<span class="badge safe">Marked Safe</span>\';\n          else actionCell = `<button class="btn-sm" onclick="markCase(\'${escapeHtml(txId)}\',\'CONFIRMED_FRAUD\')">Confirm Fraud</button><button class="btn-sm" onclick="markCase(\'${escapeHtml(txId)}\',\'FALSE_POSITIVE\')">Mark Safe</button>`;\n        }\n        return `<tr>\n          <td>${escapeHtml(ts)}</td>\n          <td>${escapeHtml(ttype)}</td>\n          <td>${fmtKes(amt)}</td>\n          <td><button class="acct-link" onclick="openAccountDrawer(\'${escapeHtml(sender)}\')">${escapeHtml(sender)}</button> &rarr; <button class="acct-link" onclick="openAccountDrawer(\'${escapeHtml(recipient)}\')">${escapeHtml(recipient)}</button></td>\n          <td><span class="badge ${v.flagged ? \'warn\' : \'safe\'}">${v.flagged ? \'FLAGGED\' : \'SAFE\'}</span></td>\n          <td>${escapeHtml(reason)}</td>\n          <td>${actionCell}</td>\n        </tr>`;\n      }).join(\'\');\n    }\n\n    async function markCase(txId, status) {\n      const body = {}; body[SCHEMA.disposition_key] = status;\n      await fetch(`/logs/${encodeURIComponent(txId)}/disposition`, {\n        method: \'PATCH\', headers: { \'Content-Type\': \'application/json\' }, body: JSON.stringify(body)\n      });\n      loadHistory();\n    }\n\n    // ACCOUNT SUMMARY DRAWER\n    async function openAccountDrawer(accountId) {\n      if (!accountId || accountId === \'—\') return;\n      document.getElementById(\'accountDrawer\').classList.add(\'open\');\n      document.getElementById(\'drawerTitle\').textContent = accountId;\n      document.getElementById(\'drawerBody\').innerHTML = \'<p style="color:var(--muted);">Loading recent activity...</p>\';\n      try {\n        const res = await fetch(`/accounts/${encodeURIComponent(accountId)}`);\n        if (!res.ok) throw new Error(\'Could not fetch account history.\');\n        const data = await res.json();\n        const txs = Array.isArray(data) ? data : (data.transactions || data.timeline || data.history || data.items || []);\n        let sent = 0, received = 0, flagged = 0;\n        txs.forEach(t => {\n          const amt = Number(t.amount_kes ?? t.amount ?? 0);\n          const s = t.origin_account_id || t.sender || \'\';\n          const r = t.vendor_hash || t.recipient || \'\';\n          if (s === accountId) sent += amt;\n          if (r === accountId) received += amt;\n          if (extractVerdict(t).flagged) flagged++;\n        });\n        const totalOut = data.total_outbound_kes ?? data.outbound_total ?? sent;\n        const totalIn = data.total_inbound_kes ?? data.inbound_total ?? received;\n        const flagCount = data.flagged_count ?? flagged;\n\n        document.getElementById(\'drawerBody\').innerHTML = `\n          <div class="drawer-stats">\n            <div class="drawer-stat"><div class="k">Total Sent</div><div class="v">${fmtKes(totalOut)}</div></div>\n            <div class="drawer-stat"><div class="k">Total Received</div><div class="v">${fmtKes(totalIn)}</div></div>\n            <div class="drawer-stat"><div class="k">Flagged</div><div class="v" style="color:${flagCount ? \'var(--warn-text)\' : \'var(--safe-text)\'};">${flagCount} / ${txs.length}</div></div>\n          </div>\n          ${txs.length ? txs.map(t => {\n            const v = extractVerdict(t);\n            const s = t.origin_account_id || t.sender || \'\';\n            const r = t.vendor_hash || t.recipient || \'\';\n            const role = s === accountId ? \'Sent to \' + r : \'Received from \' + s;\n            const amt = Number(t.amount_kes ?? t.amount ?? 0);\n            const ts = t.timestamp ? new Date(t.timestamp).toLocaleString([], {month:\'short\', day:\'numeric\', hour:\'2-digit\', minute:\'2-digit\'}) : \'\';\n            return `<div class="timeline-item">\n              <div class="timeline-top">\n                <strong>${fmtKes(amt)}</strong>\n                <span class="badge ${v.flagged ? \'warn\' : \'safe\'}">${v.flagged ? \'FLAGGED\' : \'SAFE\'}</span>\n              </div>\n              <div style="color:#374151;">${escapeHtml(friendlyType(t.tx_type || t.type))} &middot; ${escapeHtml(role)}</div>\n              <div style="color:var(--muted); font-size:12px; margin-top:3px;">${escapeHtml(ts)} &middot; ${escapeHtml(plainReasons(v.reasons, v.flagged)[0] || \'\')}</div>\n            </div>`;\n          }).join(\'\') : \'<p style="color:var(--muted);">No transactions recorded for this account yet.</p>\'}\n        `;\n      } catch (err) {\n        document.getElementById(\'drawerBody\').innerHTML = `<div class="verdict-box warn"><p class="verdict-sub">${escapeHtml(err.message)}</p></div>`;\n      }\n    }\n\n    function closeAccountDrawer() { document.getElementById(\'accountDrawer\').classList.remove(\'open\'); }\n\n    // SETTINGS & PERFORMANCE MODAL\n    async function openSettings() {\n      document.getElementById(\'settingsModal\').classList.add(\'open\');\n      document.getElementById(\'settingsMsg\').textContent = \'\';\n      try {\n        const s = await (await fetch(\'/settings\')).json();\n        const val = Number(s.threshold ?? s.active_threshold ?? s.cutoff ?? 0.20);\n        document.getElementById(\'cutoffSlider\').value = val;\n        document.getElementById(\'cutoffVal\').textContent = val.toFixed(2);\n      } catch {}\n    }\n\n    function closeSettings() { document.getElementById(\'settingsModal\').classList.remove(\'open\'); }\n\n    function pctFmt(val) {\n      if (val == null || isNaN(Number(val))) return \'—\';\n      const n = Number(val);\n      return (n <= 1 ? n * 100 : n).toFixed(2) + \'%\';\n    }\n\n    function findMetricBlock(obj, keywords) {\n      if (!obj || typeof obj !== \'object\') return null;\n      const roots = [obj, obj.models, obj.comparison, obj.benchmarks, obj.holdout, obj.results].filter(x => x && typeof x === \'object\');\n      for (const r of roots) {\n        for (const [k, v] of Object.entries(r)) {\n          if (v && typeof v === \'object\' && keywords.some(kw => k.toLowerCase().includes(kw))) {\n            return v;\n          }\n        }\n      }\n      return null;\n    }\n\n    async function loadBenchmarks() {\n      const tbody = document.getElementById(\'benchRows\');\n      try {\n        const m = await (await fetch(\'/metrics\')).json();\n        const xgb = findMetricBlock(m, [\'xgb\', \'hybrid\', \'anomaly_guard\', \'primary\']);\n        const iso = findMetricBlock(m, [\'iso\', \'forest\']);\n        const stat = findMetricBlock(m, [\'static\', \'legacy\', \'rule\', \'50k\']);\n        const entries = [\n          [\'Anomaly Guard (XGBoost)\', xgb || { f1: 0.9975, precision: 0.9987, recall: 0.9962, fpr: 0.0001 }],\n          [\'Isolation Forest (Baseline)\', iso || { f1: 0.6335, precision: 0.6547, recall: 0.6138, fpr: 0.0259 }],\n          [\'Static Rule (> KES 50,000)\', stat || { f1: 0.2309, precision: 0.1328, recall: 0.8850, fpr: 0.4624 }],\n        ];\n        tbody.innerHTML = entries.map(([name, d]) => {\n          const f1 = Number(d.f1 ?? d.f1_score ?? 0).toFixed(4);\n          const prec = pctFmt(d.precision);\n          const rec = pctFmt(d.recall);\n          const fpr = pctFmt(d.fpr ?? d.false_positive_rate);\n          return `<tr><td><strong>${escapeHtml(name)}</strong></td><td>${f1}</td><td>${prec}</td><td>${rec}</td><td>${fpr}</td></tr>`;\n        }).join(\'\');\n      } catch {\n        tbody.innerHTML = \'<tr><td colspan="5" style="color:var(--warn-text);">Could not load /metrics.</td></tr>\';\n      }\n    }\n\n    async function runSpeedTest() {\n      const btn = document.getElementById(\'speedBtn\');\n      const out = document.getElementById(\'speedOut\');\n      btn.disabled = true; btn.textContent = \'Running 20 checks...\';\n      out.innerHTML = \'<div style="font-size:13px; color:var(--muted);">Sending 20 concurrent requests to /score...</div>\';\n\n      const tStart = performance.now();\n      const tasks = Array.from({ length: 20 }, (_, i) => {\n        const isDrain = i % 4 === 0;\n        const amt = isDrain ? 185000 : 250 + i * 50;\n        const oldB = isDrain ? 185000 : 20000;\n        const payload = buildPayload({\n          txId: makeTxId(\'SPD\' + (i + 1)),\n          txType: isDrain ? \'CASH_OUT\' : \'PAYMENT\',\n          amount: amt,\n          sender: \'SPEED-USER-\' + (i + 1),\n          recipient: isDrain ? \'AGENT-4421\' : \'TILL-NAIVAS\',\n          oldOrig: oldB,\n          newOrig: Math.max(0, oldB - amt),\n          timestamp: buildIsoTime(isDrain ? \'night\' : \'day\', 0),\n        });\n        const rStart = performance.now();\n        return scoreOne(payload)\n          .then(d => ({ ok: true, rtt: performance.now() - rStart, srv: Number(d.latency_ms || 0) }))\n          .catch(() => ({ ok: false, rtt: performance.now() - rStart, srv: 0 }));\n      });\n\n      const res = await Promise.all(tasks);\n      const wallMs = performance.now() - tStart;\n      const ok = res.filter(r => r.ok);\n      const rtts = ok.map(r => r.rtt).sort((a, b) => a - b);\n      const avgRtt = rtts.length ? rtts.reduce((a, b) => a + b, 0) / rtts.length : 0;\n      const p95Rtt = rtts.length ? rtts[Math.min(rtts.length - 1, Math.floor(rtts.length * 0.95))] : 0;\n      const maxRtt = rtts.length ? rtts[rtts.length - 1] : 0;\n      const avgSrv = ok.length ? ok.reduce((a, b) => a + b.srv, 0) / ok.length : 0;\n      const pass = ok.length === 20 && maxRtt <= 1500;\n\n      out.innerHTML = `\n        <div class="verdict-box ${pass ? \'safe\' : \'warn\'}" style="padding:12px 14px; margin:8px 0 0;">\n          <strong style="font-size:14px;">${pass ? \'PASS &mdash; All 20 requests finished inside the 1,500 ms target\' : \'Completed \' + ok.length + \'/20 requests (max \' + maxRtt.toFixed(0) + \' ms)\'}</strong>\n        </div>\n        <div class="speed-grid">\n          <div class="speed-box"><div class="k">Success</div><div class="v">${ok.length} / 20</div></div>\n          <div class="speed-box"><div class="k">Avg Server</div><div class="v">${avgSrv.toFixed(1)} ms</div></div>\n          <div class="speed-box"><div class="k">Avg / P95 RTT</div><div class="v">${avgRtt.toFixed(0)} / ${p95Rtt.toFixed(0)} ms</div></div>\n          <div class="speed-box"><div class="k">Slowest RTT</div><div class="v">${maxRtt.toFixed(0)} ms</div></div>\n          <div class="speed-box"><div class="k">Total Wall</div><div class="v">${(wallMs / 1000).toFixed(2)} s</div></div>\n          <div class="speed-box"><div class="k">Throughput</div><div class="v">${(ok.length / (wallMs / 1000)).toFixed(1)} req/s</div></div>\n        </div>\n      `;\n      btn.disabled = false; btn.textContent = \'Run 20-Request Test\';\n    }\n\n    async function saveCutoff() {\n      const msg = document.getElementById(\'settingsMsg\');\n      const body = {}; body[SCHEMA.threshold_key] = Number(document.getElementById(\'cutoffSlider\').value);\n      const res = await fetch(\'/settings/threshold\', {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\', \'X-Admin-Token\': document.getElementById(\'adminPin\').value },\n        body: JSON.stringify(body),\n      });\n      msg.style.color = res.ok ? \'var(--safe-text)\' : \'var(--warn-text)\';\n      msg.textContent = res.ok ? `Sensitivity saved (${Number(body[SCHEMA.threshold_key]).toFixed(2)}).` : \'Invalid Admin PIN.\';\n    }\n\n    async function clearHistory() {\n      if (!confirm(\'Clear all saved transaction history?\')) return;\n      const msg = document.getElementById(\'settingsMsg\');\n      const res = await fetch(\'/admin/logs\', { method: \'DELETE\', headers: { \'X-Admin-Token\': document.getElementById(\'adminPin\').value } });\n      msg.style.color = res.ok ? \'var(--safe-text)\' : \'var(--warn-text)\';\n      msg.textContent = res.ok ? \'History cleared.\' : \'Invalid Admin PIN.\';\n      if (res.ok) loadHistory();\n    }\n\n    // Cold-start aware health check\n    const pill = document.getElementById(\'statusPill\');\n    const wakeBanner = document.getElementById(\'wakeBanner\');\n    const wakeTimer = setTimeout(() => {\n      pill.textContent = \'Waking up...\';\n      pill.className = \'pill waking\';\n      wakeBanner.classList.add(\'show\');\n    }, 2200);\n\n    fetch(\'/health\').then(r => r.json()).then(() => {\n      clearTimeout(wakeTimer);\n      pill.textContent = \'Ready\';\n      pill.className = \'pill\';\n      wakeBanner.classList.remove(\'show\');\n    }).catch(() => {\n      clearTimeout(wakeTimer);\n      pill.textContent = \'Offline\';\n      pill.className = \'pill offline\';\n      wakeBanner.classList.remove(\'show\');\n    });\n\n    updateBalanceHint();\n  \n    // INTERACTIVE QUICK TOUR\n    let tourIdx = 0;\n    let highlightedEl = null;\n\n    const TOUR_STEPS = [\n      {\n        tab: \'check\',\n        selector: \'.examples\',\n        title: \'1. Check a Single Transfer\',\n        body: \'Enter any mobile money transfer below, or click one of the 4 quick examples to test how Anomaly Guard spots fraud. Click "Try Live Example" to see it work right now.\',\n        showDemo: true,\n      },\n      {\n        tab: \'check\',\n        selector: \'#resultArea\',\n        title: \'2. Read the Instant Result\',\n        body: \'You get a clear green (Safe) or red (Warning) verdict, a risk percentage, and plain-English reasons. Technical details are tucked away underneath if needed.\',\n        showDemo: false,\n      },\n      {\n        tab: \'upload\',\n        selector: \'#dropzone\',\n        title: \'3. Check a Whole Spreadsheet (CSV)\',\n        body: \'Have many transactions? Download the sample CSV, drop it here to check every row at once, and export the checked results back to CSV.\',\n        showDemo: false,\n      },\n      {\n        tab: \'history\',\n        selector: \'#tab-history .card\',\n        title: \'4. Review History & Account Activity\',\n        body: \'Every checked transfer is saved here. Search by account or amount, confirm or dismiss flagged alerts, or click any blue account name to view its activity timeline.\',\n        showDemo: false,\n      },\n    ];\n\n    function clearTourHighlight() {\n      if (highlightedEl) {\n        highlightedEl.classList.remove(\'tour-highlight\');\n        highlightedEl = null;\n      }\n    }\n\n    function renderTourStep() {\n      const step = TOUR_STEPS[tourIdx];\n      const tabIndex = { check: 0, upload: 1, history: 2 }[step.tab];\n      const tabBtn = document.querySelectorAll(\'.tab\')[tabIndex];\n      switchTab(step.tab, tabBtn);\n\n      clearTourHighlight();\n      setTimeout(() => {\n        const el = document.querySelector(step.selector);\n        if (el) {\n          el.classList.add(\'tour-highlight\');\n          el.scrollIntoView({ behavior: \'smooth\', block: \'center\' });\n          highlightedEl = el;\n        }\n      }, 60);\n\n      document.getElementById(\'tourStepLabel\').textContent = `Step ${tourIdx + 1} of ${TOUR_STEPS.length}`;\n      document.getElementById(\'tourTitle\').textContent = step.title;\n      document.getElementById(\'tourBody\').textContent = step.body;\n      document.getElementById(\'tourBackBtn\').style.display = tourIdx === 0 ? \'none\' : \'inline-block\';\n      document.getElementById(\'tourDemoBtn\').style.display = step.showDemo ? \'inline-block\' : \'none\';\n      document.getElementById(\'tourNextBtn\').textContent = tourIdx === TOUR_STEPS.length - 1 ? \'Finish\' : \'Next\';\n      document.getElementById(\'tourCard\').classList.add(\'open\');\n    }\n\n    function startTour() {\n      tourIdx = 0;\n      renderTourStep();\n    }\n\n    function nextTourStep() {\n      if (tourIdx < TOUR_STEPS.length - 1) {\n        tourIdx++;\n        renderTourStep();\n      } else {\n        endTour();\n      }\n    }\n\n    function prevTourStep() {\n      if (tourIdx > 0) {\n        tourIdx--;\n        renderTourStep();\n      }\n    }\n\n    async function runTourDemo() {\n      await runExample(\'drain\');\n      tourIdx = 1;\n      renderTourStep();\n    }\n\n    function endTour() {\n      clearTourHighlight();\n      document.getElementById(\'tourCard\').classList.remove(\'open\');\n    }\n\n  </script>\n</body>\n</html>\n'
